(()=>{const lab=document.getElementById('wine-lab'),play=document.getElementById('wine-play'),reset=document.getElementById('wine-reset'),status=document.getElementById('wine-lab-status'),steps=[...document.querySelectorAll('[data-lab-stage]')];let timer=null,index=-1,running=false;const notes=['Measure: the notebook prepares physicochemical features and encodes wine type. No new sample is being entered here.','Estimate: the fitted regressor maps prepared features to a numeric quality estimate. This walkthrough does not run a trained model.','Evaluate: tuned Random Forest recorded test MAE 0.558 and R² 0.346. Its larger training/test gap warrants further validation.'];function stop(){clearTimeout(timer);timer=null;running=false;lab.classList.remove('wine-lab-running');}function show(){steps.forEach((s,i)=>s.classList.toggle('active',i===index));status.textContent=notes[index];}function next(){index++;if(index>=steps.length){stop();play.textContent='Replay walkthrough ↻';return;}show();timer=setTimeout(next,2800);}play.addEventListener('click',()=>{if(running){stop();play.textContent='Resume walkthrough ▶';return;}if(index>=2)index=-1;running=true;lab.classList.add('wine-lab-running');play.textContent='Pause walkthrough Ⅱ';if(index<0)next();else timer=setTimeout(next,2800);});reset.addEventListener('click',()=>{stop();index=-1;steps.forEach(s=>s.classList.remove('active'));status.textContent='Press play to follow the testing process.';play.textContent='Play walkthrough ▶';});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running){stop();play.textContent='Resume walkthrough ▶';}});})();
